/**
 * Why a license field appears in a diff. `changed` means the two sides hold different values — usually a field adjusted for this organization, since a template edit is otherwise propagated onto the license; a propagation still in flight, or one refused because the merged values no longer satisfy the schema, also reads as `changed`. `only_in_license` and `only_in_template` mean the template changed shape and the license has not (yet) followed.
 */
export const zLicenseDifferenceKind = z.enum([
    'changed',
    'only_in_license',
    'only_in_template'
]);

export const zLicenseFieldDifference = z.object({
    field: z.string(),
    kind: zLicenseDifferenceKind,
    license_value: z.unknown(),
    template_value: z.unknown()
});

/**
 * How an organization's license differs from its template today. Templates carry no version, so this names which license fields differ rather than which revision they came from.
 */
export const zOrganizationLicenseDiffResponse = z.object({
    organization_id: zKsuid,
    template_id: zKsuid,
    differences: z.array(zLicenseFieldDifference),
    count: z.int()
});

/**
 * What happened to an organization's license. `INSTANTIATED` is a template being stamped onto the organization through the single-organization license route: `template_id` names it and `new_value` carries the whole set of values copied. `ADJUSTED` is one license field moved for this organization alone: `field` names it, and `old_value` and `new_value` are that field's values on either side of the change. `SET` is the organization's license set through the batch migrate route — moved from another template, or granted its first, whichever it held before the run: `template_id` names the template it now holds, `previous_template_id` the one it came from (absent for a first license), and `old_value` and `new_value` carry the whole set of values on either side (`old_value` absent to match). `TEMPLATE_SYNCED` is the license following its own template after that template's values were updated — an automatic propagation, not an operator's migrate: `template_id` names the template followed, and `old_value` and `new_value` carry the whole set of values on either side. Adjusted fields keep their values through it.
 */
export const zLicenseChangeType = z.enum([
    'INSTANTIATED',
    'ADJUSTED',
    'SET',
    'TEMPLATE_SYNCED'
]);

/**
 * One entry in an organization's license history. Entries are immutable and append-only: nothing edits one, and a correction is a later entry.
 */
export const zOrganizationLicenseChangeResponse = z.object({
    id: zKsuid,
    product_id: zKsuid,
    organization_id: zKsuid,
    license_id: zKsuid,
    type: zLicenseChangeType,
    template_id: zKsuid.optional(),
    previous_template_id: zKsuid.optional(),
    field: z.string().optional(),
    old_value: z.unknown().optional(),
    new_value: z.unknown().optional(),
    changed_at: z.iso.datetime()
});

/**
 * What to do with a license field whose value differs from the template the organization currently holds. `CARRY_FORWARD`, the default, keeps that value on the migrated license, so a bespoke arrangement survives a tier change. `DISCARD` takes the target template whole and clears all recorded adjustments, including fields already equal to the template.
 * A difference is either someone adjusting that customer or the template moving after the copy was taken, and the difference alone does not say which. `CARRY_FORWARD` therefore preserves a stale copy as readily as a bespoke deal. Read the diff between the two templates before choosing.
 */
export const zLicenseMigrationDifferencePolicy = z.enum(['CARRY_FORWARD', 'DISCARD']);

/**
 * What happened to one organization in a migration run. `CHANGED` means its license was written and its provenance stamped onto the target — moved from another tier, or granted its first, whichever it held before the run; `previous_template_id` on the history entry says which. Clearing recorded adjustments also counts as `CHANGED` even when no value moves. `UNCHANGED` means it already held exactly those values and adjustment records from that same template, so nothing was written. `FAILED` means the write was attempted and refused; `error` says why, and the rest of the batch was unaffected.
 */
export const zLicenseMigrationOutcome = z.enum([
    'CHANGED',
    'UNCHANGED',
    'FAILED'
]);

/**
 * Moves a set of organizations onto one license template. Each license takes the target template's values and its provenance is restamped, so the record says which tier the customer is on now. This is not an adjustment: adjusting cannot move provenance, by design.
 * By default a value that differs from the template the organization currently holds is carried forward onto the new license, so a bespoke arrangement survives the move. See `on_difference`.
 * Supply exactly one selection — `organization_ids` or `from_template_id`. Supplying both, or neither, is refused.
 */
export const zOrganizationLicenseMigrationRequest = z.object({
    template_id: zKsuid,
    organization_ids: z.array(zKsuid).max(500).optional(),
    from_template_id: zKsuid.optional(),
    on_difference: zLicenseMigrationDifferencePolicy.optional().default('CARRY_FORWARD')
});

/**
 * What one migration did to one organization.
 */
export const zOrganizationLicenseMigrationResult = z.object({
    organization_id: zKsuid,
    outcome: zLicenseMigrationOutcome,
    previous_template_id: zKsuid.optional(),
    changes: z.array(zLicenseFieldDifference),
    count: z.int(),
    error: zApiError.optional()
});

/**
 * The receipt for one migration run: every organization it considered and what happened to each. Results are ordered by organization identifier.
 */
export const zOrganizationLicenseMigrationResponse = z.object({
    template_id: zKsuid,
    migrated_at: z.iso.datetime(),
    results: z.array(zOrganizationLicenseMigrationResult),
    count: z.int(),
    changed: z.int(),
    unchanged: z.int(),
    failed: z.int()
});

/**
 * Narrows a search over a product's organizations and the licenses they hold.
 */
export const zOrganizationLicenseFilter = z.object({
    organization_ids: z.array(zKsuid).optional(),
    license_template_ids: z.array(zKsuid).optional(),
    licensed: z.boolean().optional()
});

/**
 * Field to sort by. `instantiated_at` puts organizations holding no license last, because they were never stamped, in both directions.
 */
export const zOrganizationLicenseSortField = z.enum(['organization_name', 'instantiated_at']).default('organization_name');

export const zOrganizationLicenseSearchRequest = zSearchRequest.and(z.object({
    filter: zOrganizationLicenseFilter.optional(),
    sort_by: zOrganizationLicenseSortField.optional()
}));

/**
 * One of the product's organizations and the license it holds, if any. The organization is the subject: one that has never been licensed is listed with `license` absent rather than omitted from the results, because an unlicensed customer is exactly what an operator is looking for half the time.
 */
export const zOrganizationLicenseSummaryResponse = z.object({
    organization_id: zKsuid,
    organization_name: z.string(),
    license: zOrganizationLicenseResponse.optional()
});

export const zOrganizationLicenseSearchResponse = zPagedListResponse.and(z.object({
    items: z.array(zOrganizationLicenseSummaryResponse)
}));

export const zOrganizationLicenseHistoryResponse = zPagedListResponse.and(z.object({
    items: z.array(zOrganizationLicenseChangeResponse)
}));

/**
 * Narrows the history of one organization's license.
 */
export const zOrganizationLicenseHistoryFilter = z.object({
    types: z.array(zLicenseChangeType).optional(),
    changed_after: z.iso.datetime().optional(),
    changed_before: z.iso.datetime().optional()
});

export const zOrganizationLicenseHistorySearchRequest = zSearchRequest.and(z.object({
    filter: zOrganizationLicenseHistoryFilter.optional(),
    sort_by: z.enum(['changed_at']).optional().default('changed_at')
}));

/**
 * One absolute snapshot of what an organization has used. Report as often as you like — the cadence is your decision, not a contract shared with Anchor. Anchor stores every report and never adds them together, so a retry cannot double-count, and a report that never arrived corrects itself on the next one.
 */
export const zUsageReportRequest = z.object({
    key: z.string().max(120),
    value: z.number().gte(0),
    from: z.iso.datetime().optional(),
    to: z.iso.datetime().optional()
});

/**
 * One stored usage report. An observation is immutable. A correction is a new observation, never an edit of this one.
 */
export const zUsageObservationResponse = z.object({
    id: zKsuid,
    product_id: zKsuid,
    organization_id: zKsuid,
    key: z.string(),
    value: z.number(),
    from: z.iso.datetime().optional(),
    to: z.iso.datetime().optional(),
    observed_at: z.iso.datetime()
});

/**
 * Which level of the continuous-aggregate cascade to read. Every level reports the last observation per bucket — never a sum or an average, because the underlying values are snapshots and the last one in a bucket already is the bucket's value. Finer levels are retained for a shorter time than coarser ones; see docs/adr/0005-timescaledb-for-usage-history.md.
 */
export const zUsageGranularity = z.enum([
    'MINUTE',
    'HOUR',
    'DAY'
]);

/**
 * One bucket of an organization's usage series.
 */
export const zUsageSeriesPointResponse = z.object({
    bucket: z.iso.datetime(),
    value: z.number(),
    from: z.iso.datetime().optional(),
    to: z.iso.datetime().optional()
});

export const zUsageSeriesResponse = zPagedListResponse.and(z.object({
    items: z.array(zUsageSeriesPointResponse)
}));

